"}, "risk_level": "R2", "schema_version": 1, "source_commit": "a04446e57ec1fbc252a871afcec7752fb2807b14", "source_math_hash": "sha256:44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a", "source_status": "CURRENT", "source_structure_hash": "sha256:88ebb9e44bce6c46f5d7c30949b2c0a175d79e1f9dbd207c168f9078b3c440da", "source_text": "The aim of this book is to give a friendly introduction to stacks without assuming a sophisticated background with a focus on examples and applications. Unlike <CITE_0001>, it is not assumed that the reader has digested the theory of algebraic spaces. Instead, Deligne-Mumford stacks are introduced with algebraic spaces being a special case with part of the goal being to develop enough theory to prove the assertions in <CITE_0002>. The general theory of Artin stacks is to be developed in the second part. Only a fraction of the book is now available on Kresch's website.", "source_text_hash": "sha256:80fc6a20e5c91204436a32896f173bfed7582895ca8dd17118eb9839d5220721", "unit_id": "tag:03B3:item004-quote"}
